import AppKit
import MenuFoldCore

/// Watches the general pasteboard and feeds `GridModel.clipboard`. Polls `changeCount` (macOS has no
/// pasteboard notification) twice a second, only while enabled. Texts a password manager or another
/// app marks as concealed, transient or auto-generated (nspasteboard.org) are never recorded, and the
/// history lives in memory only.
@MainActor
final class ClipboardMonitor {
    static let shared = ClipboardMonitor()

    private static let ignoredTypes: Set<NSPasteboard.PasteboardType> = [
        .init("org.nspasteboard.ConcealedType"),
        .init("org.nspasteboard.TransientType"),
        .init("org.nspasteboard.AutoGeneratedType"),
        .init("com.agilebits.onepassword"),
    ]

    private weak var model: GridModel?
    private var timer: Timer?
    private var lastChangeCount = NSPasteboard.general.changeCount

    private init() {}

    func attach(to model: GridModel) {
        self.model = model
    }

    /// Starts or stops polling; the history is dropped when stopped (turning the tab off forgets it).
    func setEnabled(_ enabled: Bool) {
        if enabled {
            guard timer == nil else { return }
            lastChangeCount = NSPasteboard.general.changeCount
            // Take what is on the clipboard right now, so the tab is not empty at first.
            poll(force: true)
            let timer = Timer(timeInterval: 0.5, repeats: true) { [weak self] _ in
                MainActor.assumeIsolated { self?.poll(force: false) }
            }
            timer.tolerance = 0.2
            RunLoop.main.add(timer, forMode: .common)
            self.timer = timer
        } else {
            timer?.invalidate()
            timer = nil
            model?.clipboard = ClipboardHistory()
        }
    }

    /// Puts an entry back on the pasteboard (the user then pastes it with ⌘V) without recording
    /// the write as a new copy.
    func copy(_ entry: ClipboardEntry) {
        let pasteboard = NSPasteboard.general
        pasteboard.clearContents()
        pasteboard.setString(entry.text, forType: .string)
        lastChangeCount = pasteboard.changeCount
        model?.clipboard.add(entry.text)
    }

    private func poll(force: Bool) {
        let pasteboard = NSPasteboard.general
        guard force || pasteboard.changeCount != lastChangeCount else { return }
        lastChangeCount = pasteboard.changeCount
        let types = Set(pasteboard.types ?? [])
        guard types.isDisjoint(with: Self.ignoredTypes),
              let text = pasteboard.string(forType: .string) else { return }
        model?.clipboard.add(text)
    }
}
